INSERT INTO public.adventurer_gift_items (id, name, category, description, icon, base_bond, sort_order) VALUES
  ('90001', 'Prized Matsutake', 'Food', 'A gift for an adventurer that slightly increases Bond. A rare mushroom from Aesoland with an elegant aroma. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_PreciousMatsutake.png', 100, 1),
  ('90002', 'Black Pearl Roe', 'Food', 'A gift for an adventurer that increases Bond. Fine, plump roe lightly cured with low salt, delicate and savory. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_BlackCaviar.png', 200, 2),
  ('90003', 'Thick-Cut Tail', 'Food', 'A gift for an adventurer that greatly increases Bond. Thick, succulent tail meat from Barroth, a prized delicacy sought after by gourmands. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_DragonTail.png', 1000, 3),
  ('90004', 'Journey Cord', 'Expedition Gear', 'A gift for an adventurer that increases Bond. A common camp rope that many consider a good luck charm for new journeys. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_StartTethering.png', 100, 4),
  ('90005', 'Worn Adventurer Badge', 'Expedition Gear', 'A gift for an adventurer that increases Bond. A small badge engraved with the guild''s mark, a reminder of the nerves felt on one''s first departure. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_AdventurerBadge_Old.png', 200, 5),
  ('90006', 'Elder Dragon Banner', 'Expedition Gear', 'A gift for an adventurer that greatly increases Bond. Proof of participation in a large monster slaying, holding tremendous commemorative value. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_Strap.png', 1000, 6),
  ('90007', 'Wooden Carving', 'Models & Carvings', 'A gift for an adventurer that slightly increases Bond. A miniature figurine hand-carved from common wood, simple in design yet rustic and charming. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_WoodCarving.png', 100, 7),
  ('90008', 'Vista Display', 'Models & Carvings', 'A gift for an adventurer that increases Bond. A display model themed around cliff vistas, perfect for long-term display and collection. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_Booth.png', 200, 8),
  ('90009', 'Dome Landscape', 'Models & Carvings', 'A gift for an adventurer that greatly increases Bond. A dome-shaped landscape ornament that shifts and flows with texture as it turns. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_DomedView.png', 1000, 9),
  ('90010', 'Glowmoss Bottle', 'Natural Curios', 'A gift for an adventurer that slightly increases Bond. Glowing moss contained in a small bottle, providing gentle illumination at night. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_LuminousBottle.png', 100, 10),
  ('90011', 'Forest Amber', 'Natural Curios', 'A gift for an adventurer that increases Bond. Amber formed in the depths of ancient forests, with a warm, lustrous surface and subtle glow. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_ForestAmber.png', 200, 11),
  ('90012', 'Moonfeather Chime', 'Natural Curios', 'A gift for an adventurer that greatly increases Bond. A wind chime crafted from moon feather flowers that bloom briefly in highland passes, ringing with an airy, melodic chime in the wind. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_TsukihaneKarin.png', 1000, 12),
  ('90013', 'Outlands Poetry', 'Books & Music', 'A gift for an adventurer that slightly increases Bond. A collection of short poems and chants passed down in Outlands camps, often recited as a small ritual to ward off fatigue. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_LiteralTranslatio.png', 100, 13),
  ('90014', 'Bonfire Album', 'Books & Music', 'A gift for an adventurer that increases Bond. A photo album capturing moments of people dancing around bonfire gatherings, a keepsake of shared memories. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_BonfireAlbum.png', 200, 14),
  ('90015', 'Kulune Songbook', 'Books & Music', 'A gift for an adventurer that greatly increases Bond. A collection of song and dance scores compiled in Kulune Village, documenting local melodies and rhythms. Gifting it to an adventurer who cherishes it will bring them great joy.', '/images/gifts/ItemIcon_MusicalScore_KuluneVillage.png', 1000, 15),
  ('90016', 'Adventurer''s Charm', 'Keepsakes', 'A gift for an adventurer that slightly increases Bond. A small protective charm made with traditional braiding techniques, carrying simple yet sincere blessings. A thoughtful gift loved by all adventurers.', '/images/gifts/ItemIcon_AdventurerBodyguard.png', 100, 16),
  ('90017', 'Exploration Badge', 'Keepsakes', 'A gift for an adventurer that increases Bond. A metal badge bearing the guild''s mark, solidly crafted with smooth, rounded edges. A thoughtful gift loved by all adventurers.', '/images/gifts/ItemIcon_KeepsakeDadge.png', 200, 17),
  ('90018', 'Journey Memento', 'Keepsakes', 'A gift for an adventurer that greatly increases Bond. A finely crafted travel photo album that perfectly preserves every memory of the journey. A thoughtful gift loved by all adventurers.', '/images/gifts/ItemIcon_JourneySouvenirs.png', 1000, 18)
